describe('Notification Panel Slide In', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should display notification panel sliding in from the top', () => {
    cy.get('[data-testid="trigger-notification"]').click();

    cy.get('[data-testid="notification-panel"]')
      .should('be.visible')
      .and('have.css', 'transform')
      .then((transform) => {
        expect(transform).not.to.equal('none');
      });

    cy.get('[data-testid="notification-panel"]')
      .should('have.css', 'top', '0px');

    cy.get('[data-testid="notification-panel"]')
      .should('have.css', 'animation')
      .and('include', 'slideDown');
  });

  it('should handle multiple notifications in the panel', () => {
    cy.get('[data-testid="trigger-notification"]').click();
    cy.get('[data-testid="trigger-notification"]').click();
    cy.get('[data-testid="trigger-notification"]').click();

    cy.get('[data-testid="notification-panel"]')
      .should('be.visible');

    cy.get('[data-testid="notification-item"]')
      .should('have.length', 3);

    cy.get('[data-testid="notification-panel"]')
      .should('have.css', 'top', '0px');
  });

  it('should close notification panel when close button is clicked', () => {
    cy.get('[data-testid="trigger-notification"]').click();

    cy.get('[data-testid="notification-panel"]')
      .should('be.visible');

    cy.get('[data-testid="close-notification"]').click();

    cy.get('[data-testid="notification-panel"]')
      .should('not.be.visible');
  });

  it('should auto-dismiss notification after timeout', () => {
    cy.get('[data-testid="trigger-notification"]').click();

    cy.get('[data-testid="notification-panel"]')
      .should('be.visible');

    cy.get('[data-testid="notification-panel"]', { timeout: 6000 })
      .should('not.be.visible');
  });

  it('should handle empty notification panel gracefully', () => {
    cy.get('[data-testid="notification-panel"]')
      .should('not.exist');

    cy.get('[data-testid="trigger-notification"]').click();

    cy.get('[data-testid="notification-panel"]')
      .should('be.visible')
      .and('have.css', 'top', '0px');
  });
});
